IF EXISTS(SELECT 1 FROM dbo.DetallePago WHERE FechaAnulacion<FechaPago OR Monto<>Capital+Interes+ManejoCuenta+SeguroAuto+SeguroVida) THROW 52702,'Pago incoherente.',1;
